  "ui.3907d07b3bee": {
    "zh": "当前为自动模式，未固定某个候选，不默认选择第一名。打开选片窗口或执行选片时，按语义、实际配音时长和素材延长情况综合评分；窗口中会显示实际参考候选。无成功配音时等待配音完成，已有选片和视频保留原依赖。",
    "en": "It is currently in automatic mode, a candidate is not fixed, and the first place is not selected by default. When you open the film selection window or perform film selection, you will be given a comprehensive score based on semantics, actual dubbing duration, and material extension; the actual reference candidates will be displayed in the window. If there is no successful dubbing, wait for the dubbing to be completed. Existing selected films and videos will retain their original dependencies."
  },
  "ui.b955e3930f7a": {
    "zh": "当前固定使用标记的参考候选。恢复自动选择只保存自动模式并清除此前人工范围，不会立即执行选片；已有选片和视频保留原依赖。",
    "en": "Currently fixed use of tagged reference candidates. Restoring automatic selection only saves the automatic mode and clears the previous manual range. Film selection will not be performed immediately; existing film selections and videos retain their original dependencies."
  },
