  "ui.6b8129bef357": {
    "zh": "素材工作与独立检索更新：冻结配置、持久检查点、共用 CLI 管线锁。",
    "en": "Material work and independent retrieval updates: frozen configurations, persistent checkpoints, shared CLI pipeline locks."
  },
  "ui.7f997771ef22": {
    "zh": "规范化分镜召回设置；全默认返回 None，payload 与旧版逐字节一致以复用历史版本。",
    "en": "Standardized storyboard recall settings; returns None by default, and the payload is byte-for-byte consistent with the old version to reuse historical versions."
  },
  "ui.87b223684d79": {
    "zh": "按内容寻址定位查询文件并复验 sha256；防止 inputs 被清理或篡改后用错文件。",
    "en": "Query files by content addressing and re-verify sha256; prevent inputs from being cleaned or tampered with and use the wrong file."
  },
  "ui.3c772a8db10c": {
    "zh": "源内全部镜头及可见性；overlays 可由调用方预先取好，避免逐镜头全表扫描。",
    "en": "All shots and visibility in the source; overlays can be pre-fetched by the caller to avoid full table scanning one by one."
  },
